function [A,B,C,U,V,E]=mvntfTV(X,A,B,C,lambda,mu,R,L)
X1=tens2mat(X,1);  % X1 is IxJK
X2=tens2mat(X,2);  % X2 is JxIK (or smaller dimensions if compression was done)
X3=tens2mat(X,3);  % X3 is KxJI (idem)
[I,J,K]=size(X);
L_vec=ones(1,R)*L;
indU=[0 cumsum(L_vec)];
indV=[0 cumsum(L_vec)];
objNew=0.5*norm(X1-A*myKr(C,B,ones(1,R),ones(1,R)*L)','fro');
E=cell(1,R);
U=A;
V=B;
for r=1:R
    Ar=A(:,indU(r)+1:indU(r+1));
    Br=B(:,indV(r)+1:indV(r+1));
    E{r}=Ar*Br';
end
param2.verbose=1;
param2.max_iter=20;
param2.verbose = 0;
delta=0.4;
while 1
    objOld=objNew;
    %%%%%%update A
    M=myKr(C,B,ones(1,R),ones(1,R)*L);
    A=A.*(X1*M+mu*U+delta*ones(I,J)*B)./(A*M'*M+mu*A+delta*A*B'*B+1e-4);
    %%%%%%update B
    M=myKr(C,A,ones(1,R),ones(1,R)*L);
    B=B.*(X2*M+mu*V+delta*ones(J,I)*A)./(B*M'*M+mu*B+delta*B*A'*A+1e-4);    
    temp=0;
    %%%%%%update U and V
    for r=1:R
        Ur=U(:,indU(r)+1:indU(r+1));
        Vr=V(:,indV(r)+1:indV(r+1));
        Ar=A(:,indU(r)+1:indU(r+1));
        Br=B(:,indV(r)+1:indV(r+1));
        Ur=Ur.*(E{r}*Vr+Ar)./(Ur*Vr'*Vr+Ur+1e-4);
        Vr=Vr.*(E{r}'*Ur+Br)./(Vr*Ur'*Ur+Vr+1e-4);
        U(:,indU(r)+1:indU(r+1))=Ur;
        V(:,indU(r)+1:indU(r+1))=Vr;
        [E{r},obj]= prox_TV(Ur*Vr',lambda/mu,param2);
        temp=temp+TV_norm(E{r});
    end

    M=myKr2(A,B,ones(1,R)*L,ones(1,R)*L);
    %%%%%%update C

    C=C.*((X3*M)./(C*M'*M+1e-4));
    objNew=0.5*norm(X1-A*myKr(C,B,ones(1,R),ones(1,R)*L)','fro')+mu*(norm(A-U,'fro')+norm(B-V,'fro'))+temp;
    tol=abs(objNew-objOld)/objOld;
    if(tol<1e-4)
        break;
    end
    fprintf(strcat(num2str(objNew),'\t',num2str(tol),'\n'));
end

end

function y = TV_norm(u)


        [dx, dy] = gradient_op(u);

temp = sqrt(abs(dx).^2 + abs(dy).^2);
y = sum(temp(:));

end

function [sol,obj] = prox_TV(b, lambda, param)
% PROX_TV - Total variation proximal operator
%
% sol = prox_TV(y, lambda, param) solves:
%
%   min_{x} ||y - x||_2^2 + lambda * ||x||_{TV}
%
% The input argument param contains the following fields:
%
%   - max_iter: max. nb. of iterations (default: 200)
%
%   - rel_obj: minimum relative change of the objective value (default:
%   1e-4)
%       The algorithm stops if
%           | f(x(t))-f(x(t-1)) | / f(x(t)) < rel_obj,
%       where x(t) is the estimate of the solution at iteration t.
%
%   - verbose: 0 no log, 1 a summary log at convergence, 2 print main
%   steps (default: 1)
%
%
%
% Reference:
% [1] A. Beck and  M. Teboulle, "Fast gradient-based algorithms for
% constrained Total Variation Image Denoising and Deblurring Problems", 
% IEEE Transactions on Image Processing, VOL. 18, NO. 11, 2419-2434, 
% November 2009.
%
%
%
% Author: Gilles Puy
% E-mail: gilles.puy@epfl.ch
% Date: October 15, 2010
%

% Optional input arguments

if nargin<3, param=struct; end

if ~isfield(param, 'rel_obj'), param.rel_obj = 1e-4; end
if ~isfield(param, 'verbose'), param.verbose = 1; end
if ~isfield(param, 'max_iter'), param.max_iter = 200; end
if size(b,2)>1
    % Initializations
    [r, s] = gradient_op(b*0);
    pold = r; qold = s;
    told = 1; prev_obj = 0;

    % Main iterations
    if param.verbose > 1
        fprintf('  Proximal TV operator:\n');
    end
    for iter = 1:param.max_iter

        % Current solution
        sol = b - lambda*div_op(r, s);

        % Objective function value
        obj = .5*norm(b(:)-sol(:), 2)^2 + lambda * TV_norm(sol);
        rel_obj = abs(obj-prev_obj)/obj;
        prev_obj = obj;

        % Stopping criterion
        if param.verbose>1
            fprintf('   Iter %i, obj = %e, rel_obj = %e\n', ...
                iter, obj, rel_obj);
        end
        if rel_obj < param.rel_obj
            crit_TV = 'TOL_EPS'; break;
        end

        % Udpate divergence vectors and project
        [dx, dy] = gradient_op(sol);
        r = r - 1/(8*lambda) * dx; s = s - 1/(8*lambda) * dy;
        weights = max(1, sqrt(abs(r).^2+abs(s).^2));
        p = r./weights; q = s./weights;

        % FISTA update
        t = (1+sqrt(4*told^2))/2;
        r = p + (told-1)/t * (p - pold); pold = p;
        s = q + (told-1)/t * (q - qold); qold = q;
        told = t;

    end

    % Log after the minimization
    if ~exist('crit_TV', 'var'), crit_TV = 'MAX_IT'; end
    if param.verbose >= 1
        fprintf(['  Prox_TV: obj = %e, rel_obj = %e,' ...
            ' %s, iter = %i\n'], obj, rel_obj, crit_TV, iter);
    end


else
    [r] = gradient_op(b*0);
    pold = r; 
    told = 1; prev_obj = 0;

    % Main iterations
    if param.verbose > 1
        fprintf('  Proximal TV operator:\n');
    end
    for iter = 1:param.max_iter

        % Current solution
        sol = b - lambda*div_op(r);

        % Objective function value
        obj = .5*norm(b(:)-sol(:), 2)^2 + lambda * TV_norm(sol);
        rel_obj = abs(obj-prev_obj)/obj;
        prev_obj = obj;

        % Stopping criterion
        if param.verbose>1
            fprintf('   Iter %i, obj = %e, rel_obj = %e\n', ...
                iter, obj, rel_obj);
        end
        if rel_obj < param.rel_obj
            crit_TV = 'TOL_EPS'; break;
        end

        % Udpate divergence vectors and project
        [dx, ~] = gradient_op(sol);
        r = r - 1/(8*lambda) * dx; 
        weights = max(1, sqrt(abs(r).^2));
        p = r./weights;

        % FISTA update
        t = (1+sqrt(4*told^2))/2;
        r = p + (told-1)/t * (p - pold); pold = p;
        told = t;

    end

    % Log after the minimization
    if ~exist('crit_TV', 'var'), crit_TV = 'MAX_IT'; end
    if param.verbose >= 1
        fprintf(['  Prox_TV: obj = %e, rel_obj = %e,' ...
            ' %s, iter = %i\n'], obj, rel_obj, crit_TV, iter);
    end

end

end

function [dx, dy] = gradient_op(I, weights_dx, weights_dy)

dx = [I(2:end, :)-I(1:end-1, :) ; zeros(1, size(I, 2))];
dy = [I(:, 2:end)-I(:, 1:end-1) , zeros(size(I, 1), 1)];

if nargin>1
    dx = dx .* weights_dx;
    dy = dy .* weights_dy;
end

end

function I = div_op(dx, dy, weights_dx, weights_dy)

if nargin > 2
    dx = dx .* conj(weights_dx);
    dy = dy .* conj(weights_dy);
end
if nargin==2
I = [dx(1, :) ; dx(2:end-1, :)-dx(1:end-2, :) ; -dx(end-1, :)];
I = I + [dy(:, 1) , dy(:, 2:end-1)-dy(:, 1:end-2) , -dy(:, end-1)];
end
if nargin==1
   I = [dx(1, :) ; dx(2:end-1, :)-dx(1:end-2, :) ; -dx(end-1, :)]; 
end

end

