% ## RMSE
% Usage: rmse = rmse(S_GT,S_E,Ab_ord,S_E_ord)
%======================================================================

function rmse = rmse(S_GT,S_E,GT_ord,E_ord)

[P,N]= size(S_E);
rmse= zeros(3,P+1);
rmse(1,:) = GT_ord;
rmse(2,:) = E_ord;
for i=1:P
    rmse(3,i) = sqrt(sum((S_GT(i,:)- S_E(rmse(2,i),:)).^2)/N);
end
% rmse(3,P+1)= sqrt(sum(rmse(3,1:P).^2));
rmse(3,P+1)= mean(rmse(3,1:P));

fprintf([repmat('%8i',1,P+1),'\n'],rmse(1:2,:)');
fprintf([repmat('%8.4f',1,P+1),'\n'],rmse(3,:)');
end

% ## SAD
% Usage: [SAD, table_acos] = sam(A_GT, A_E)
%======================================================================

function [SAD, table_acos] = sam(A_GT, A_E)
[~,N_e] = size(A_E);
[~,N_t] = size(A_GT);

table_cos = (A_E'*A_GT)./sqrt(sum(A_E.^2)'*sum(A_GT.^2));
table_acos = acos(min(max(table_cos,0.0000),1.0000));
table3 = table_acos;
if N_e < N_t
    SAD = zeros(4,N_t+1);
	SAD(1,:)=[1:N_t 0];
    for j=1:N_e   
        sam_j = min(table3(:));
        [m,n]= find(table3 == sam_j);
        SAD(2,n(1)) = m(1);
        SAD(3,n(1)) = sam_j;
        SAD(4,n(1)) = sam_j*180/pi;
        table3(m(1),:)= 100;
        table3(:,n(1))= 100;
    end
    SAD(3,N_t+1)=sum(SAD(3,1:N_t))/N_e;
    SAD(4,N_t+1)=sum(SAD(4,1:N_t))/N_e;
	format_1 = [repmat('%8i',1,N_t+1),'\n'];
	format_2 = [repmat('%8.4f',1,N_t+1),'\n'];
	fprintf(format_1,SAD(1:2,:)');
	fprintf(format_2,SAD(3:4,:)');
else 
	SAD = zeros(5,N_t+1);
    for j=1:N_t   
        SAD(1,j)=j;
        sam_j = min(table3(:));
        [m,n]= find(table3 == sam_j);
        SAD(2,n(1)) = m(1);
        SAD(3,n(1)) = sam_j;
        SAD(4,n(1)) = sam_j*180/pi;
        table3(m(1),:)= 100;
        table3(:,n(1))= 100;
    end
    SAD(3,N_t+1)=sum(SAD(3,1:N_t))/N_t;
    SAD(4,N_t+1)=sum(SAD(4,1:N_t))/N_t;
    SAD(5,1:N_t)= sqrt(sqrt(sum(A_E(:,SAD(2,1:N_t)).^2)./sum(A_GT(:,SAD(1,1:N_t)).^2)));
    format_1 = [repmat('%8i',1,N_t+1),'\n'];
    format_2 = [repmat('%8.4f',1,N_t+1),'\n'];
    fprintf(format_1,SAD(1:2,:)');
    fprintf(format_2,SAD(3:5,:)');
end
end

function [U_final, V_final, nIter_final, objhistory_final] = GNMF(X, k, W, options, U, V)
% Graph regularized Non-negative Matrix Factorization (GNMF)
%
% where
%   X
% Notation:
% X ... (mFea x nSmp) data matrix 
%       mFea  ... number of words (vocabulary size)
%       nSmp  ... number of documents
% k ... number of hidden factors
% W ... weight matrix of the affinity graph 
%
% options ... Structure holding all settings
%               options.alpha ... the regularization parameter. 
%                                 [default: 100]
%                                 alpha = 0, GNMF boils down to the ordinary NMF. 
%                                 
%
% You only need to provide the above four inputs.
%
% X = U*V'
%
% References:
% [1] Deng Cai, Xiaofei He, Xiaoyun Wu, and Jiawei Han. "Non-negative
% Matrix Factorization on Manifold", Proc. 2008 Int. Conf. on Data Mining
% (ICDM'08), Pisa, Italy, Dec. 2008. 
%
% [2] Deng Cai, Xiaofei He, Jiawei Han, Thomas Huang. "Graph Regularized
% Non-negative Matrix Factorization for Data Representation", IEEE
% Transactions on Pattern Analysis and Machine Intelligence, , Vol. 33, No.
% 8, pp. 1548-1560, 2011.  
%
%
%   version 2.0 --April/2009 
%   version 1.0 --April/2008 
%
%   Written by Deng Cai (dengcai AT gmail.com)
%

if min(min(X)) < 0
    error('Input should be nonnegative!');
end

if ~isfield(options,'error')
    options.error = 1e-5;
end
if ~isfield(options, 'maxIter')
    options.maxIter = [];
end

if ~isfield(options,'nRepeat')
    options.nRepeat = 10;
end

if ~isfield(options,'minIter')
    options.minIter = 30;
end

if ~isfield(options,'meanFitRatio')
    options.meanFitRatio = 0.1;
end

if ~isfield(options,'alpha')
    options.alpha = 100;
end

nSmp = size(X,2);

if isfield(options,'alpha_nSmp') && options.alpha_nSmp
    options.alpha = options.alpha*nSmp;    
end

if isfield(options,'weight') && strcmpi(options.weight,'NCW')
    feaSum = full(sum(X,2));
    D_half = X'*feaSum;
    X = X*spdiags(D_half.^-.5,0,nSmp,nSmp);
end

if ~isfield(options,'Optimization')
    options.Optimization = 'Multiplicative';
end

if ~exist('U','var')
    U = [];
    V = [];
end

switch lower(options.Optimization)
    case {lower('Multiplicative')} 
        [U_final, V_final, nIter_final, objhistory_final] = GNMF_Multi(X, k, W, options, U, V);
    otherwise
        error('optimization method does not exist!');
end

function [U_final, V_final, nIter_final, objhistory_final] = GNMF_Multi(X, k, W, options, U, V)
% Graph regularized Non-negative Matrix Factorization (GNMF) with
%          multiplicative update
%
% where
%   X
% Notation:
% X ... (mFea x nSmp) data matrix 
%       mFea  ... number of words (vocabulary size)
%       nSmp  ... number of documents
% k ... number of hidden factors
% W ... weight matrix of the affinity graph 
%
% options ... Structure holding all settings
%
% You only need to provide the above four inputs.
%
% X = U*V'
%
% References:
% [1] Deng Cai, Xiaofei He, Xiaoyun Wu, and Jiawei Han. "Non-negative
% Matrix Factorization on Manifold", Proc. 2008 Int. Conf. on Data Mining
% (ICDM'08), Pisa, Italy, Dec. 2008. 
%
% [2] Deng Cai, Xiaofei He, Jiawei Han, Thomas Huang. "Graph Regularized
% Non-negative Matrix Factorization for Data Representation", IEEE
% Transactions on Pattern Analysis and Machine Intelligence, , Vol. 33, No.
% 8, pp. 1548-1560, 2011.  
%
%
%   version 2.1 --Dec./2011 
%   version 2.0 --April/2009 
%   version 1.0 --April/2008 
%
%   Written by Deng Cai (dengcai AT gmail.com)
%

differror = options.error;
maxIter = options.maxIter;
nRepeat = options.nRepeat;
minIter = options.minIter - 1;
if ~isempty(maxIter) && maxIter < minIter
    minIter = maxIter;
end
meanFitRatio = options.meanFitRatio;

alpha = options.alpha;

Norm = 2;
NormV = 0;

[mFea,nSmp]=size(X);

if alpha > 0
    W = alpha*W;
    DCol = full(sum(W,2));
    D = spdiags(DCol,0,nSmp,nSmp);
    L = D - W;
    if isfield(options,'NormW') && options.NormW
        D_mhalf = spdiags(DCol.^-.5,0,nSmp,nSmp) ;
        L = D_mhalf*L*D_mhalf;
    end
else
    L = [];
end

selectInit = 1;
if isempty(U)
    U = abs(rand(mFea,k));
    V = abs(rand(nSmp,k));
else
    nRepeat = 1;
end

[U,V] = NormalizeUV(U, V, NormV, Norm);
if nRepeat == 1
    selectInit = 0;
    minIter = 0;
    if isempty(maxIter)
        objhistory = CalculateObj(X, U, V, L);
        meanFit = objhistory*10;
    else
        if isfield(options,'Converge') && options.Converge
            objhistory = CalculateObj(X, U, V, L);
        end
    end
else
    if isfield(options,'Converge') && options.Converge
        error('Not implemented!');
    end
end



tryNo = 0;
nIter = 0;
while tryNo < nRepeat   
    tryNo = tryNo+1;
    maxErr = 1;
    while(maxErr > differror)
        % ===================== update V ========================
        XU = X'*U;  % mnk or pk (p<<mn)
        UU = U'*U;  % mk^2
        VUU = V*UU; % nk^2

        if alpha > 0
            WV = W*V;
            DV = D*V;

            XU = XU + WV;
            VUU = VUU + DV;
        end

        V = V.*(XU./max(VUU,1e-10));

        % ===================== update U ========================
        XV = X*V;   % mnk or pk (p<<mn)
        VV = V'*V;  % nk^2
        UVV = U*VV; % mk^2

        U = U.*(XV./max(UVV,1e-10)); % 3mk

        nIter = nIter + 1;
        if nIter > minIter
            if selectInit
                objhistory = CalculateObj(X, U, V, L);
                maxErr = 0;
            else
                if isempty(maxIter)
                    newobj = CalculateObj(X, U, V, L);
                    objhistory = [objhistory newobj]; %#ok<AGROW>
                    meanFit = meanFitRatio*meanFit + (1-meanFitRatio)*newobj;
                    maxErr = (meanFit-newobj)/meanFit;
                else
                    if isfield(options,'Converge') && options.Converge
                        newobj = CalculateObj(X, U, V, L);
                        objhistory = [objhistory newobj]; %#ok<AGROW>
                    end
                    maxErr = 1;
                    if nIter >= maxIter
                        maxErr = 0;
                        if isfield(options,'Converge') && options.Converge
                        else
                            objhistory = 0;
                        end
                    end
                end
            end
        end
    end

    if tryNo == 1
        U_final = U;
        V_final = V;
        nIter_final = nIter;
        objhistory_final = objhistory;
    else
       if objhistory(end) < objhistory_final(end)
           U_final = U;
           V_final = V;
           nIter_final = nIter;
           objhistory_final = objhistory;
       end
    end

    if selectInit
        if tryNo < nRepeat
            %re-start
            U = abs(rand(mFea,k));
            V = abs(rand(nSmp,k));

            [U,V] = NormalizeUV(U, V, NormV, Norm);
            nIter = 0;
        else
            tryNo = tryNo - 1;
            nIter = minIter+1;
            selectInit = 0;
            U = U_final;
            V = V_final;
            objhistory = objhistory_final;
            meanFit = objhistory*10;
        end
    end
end

[U_final,V_final] = NormalizeUV(U_final, V_final, NormV, Norm);


